Consider the following class.<pre class="formula-code"><code>public class Tank
{
    private int level;
    private int capacity;

    public Tank(int cap)
    {
        capacity = cap;
        level = 0;
    }

    public int fill(int amt)
    {
        int space = capacity - level;
        if (amt &gt; space)
        {
            level = capacity;
            return amt - space;
        }
        level += amt;
        return 0;
    }

    public void drain(int amt)
    {
        level -= amt;
        if (level &lt; 0)
